module firr18_v5 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [7:0]  x,
    output reg  [15:0] y
);
    reg  [7:0]  xs [0:17];
    integer     i;
    reg  [23:0] acc;
    always @(*) acc = 8'd6 + 2 * xs[0] + 5 * xs[1] + 8 * xs[2] + 11 * xs[3] + 14 * xs[4] + 17 * xs[5] + 20 * xs[6] + 23 * xs[7] + 26 * xs[8] + 29 * xs[9] + 32 * xs[10] + 35 * xs[11] + 38 * xs[12] + 41 * xs[13] + 44 * xs[14] + 47 * xs[15] + 50 * xs[16] + 53 * xs[17];
    always @(posedge clk) begin
        if (!rst_n) begin
            for (i = 0; i < 18; i = i + 1) xs[i] <= 8'd0;
            y <= 16'd0;
        end else begin
            xs[0] <= x;
            for (i = 1; i < 18; i = i + 1) xs[i] <= xs[i-1];
            y <= acc[15:0];
        end
    end
endmodule

